"""Teacher-oriented upload readiness, support planning and model entry."""


def render_support():
    return HTML


HTML=r'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>教学支持与上传测试</title><style>
*{box-sizing:border-box;letter-spacing:0}body{margin:0;background:#f4f8fd;color:#25374e;font:15px/1.75 "Microsoft YaHei UI","Segoe UI",sans-serif}header{background:white;border-bottom:1px solid #dce5f0;padding:18px 28px;display:flex;justify-content:space-between;gap:16px}main{max-width:1160px;margin:auto;padding:28px}h1{font-size:26px;margin:5px 0 14px}h2{font-size:20px;margin:0 0 16px}h3{font-size:16px;margin:18px 0 8px}a{color:#2463dc;text-decoration:none}a:hover{text-decoration:underline}.subtle{color:#63758b;font-size:13px}nav,.actions{display:flex;gap:18px;flex-wrap:wrap}nav{border-bottom:1px solid #dce5f0;padding:18px 0}section{background:white;padding:24px;margin:24px 0;border-block:1px solid #dce5f0;scroll-margin-top:20px}.steps{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:14px}.step{padding:12px 0;border-top:3px solid #dce5f0;font-size:14px}.step.ready{border-color:#168579}.step span{display:block;color:#63758b;font-size:12px}.note{padding:12px 16px;border-left:3px solid #c58d36;background:#fff9ee;font-size:13px;color:#855417}.fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.wide{grid-column:1/-1}label{display:block;font-size:13px;color:#63758b}input,select,textarea{font:inherit;color:#25374e;background:white;width:100%;padding:10px;border:1px solid #becddf;border-radius:5px;margin-top:6px}textarea{min-height:88px;resize:vertical}button,.button{font:inherit;border:1px solid #bdcddd;background:white;color:#25374e;min-height:40px;padding:7px 16px;border-radius:6px;cursor:pointer;display:inline-flex;align-items:center}.primary{background:#2463dc;border-color:#2463dc;color:white}button:disabled{opacity:.55;cursor:not-allowed}p{margin:8px 0 16px}.support-grid{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(0,1fr);gap:30px}li{margin:9px 0}.reference{padding:12px 0;border-top:1px solid #dce5f0;font-size:13px}.history{padding:16px 0;border-top:1px solid #dce5f0;overflow-wrap:anywhere}.history strong{display:block}.checklist{display:grid;grid-template-columns:1fr 1fr;gap:14px}.checklist div{border-left:2px solid #c6d7f0;padding-left:14px}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f5f8fc;padding:18px;font-size:12px}#message:empty{display:none}#message{padding:12px;border-left:3px solid #2463dc;background:#eaf1fe}.badge{color:#148376;font-size:13px}:focus-visible{outline:3px solid #9abfff;outline-offset:3px}
@media(max-width:680px){header,main{padding:16px}.steps{grid-template-columns:repeat(2,minmax(0,1fr))}.fields,.support-grid,.checklist{grid-template-columns:minmax(0,1fr)}section{padding:18px 14px}nav{gap:12px;font-size:14px}h1{font-size:23px}}
</style></head><body><header><strong>课堂观察工作台</strong><a href="/demo2/analysis">返回课堂列表</a></header><main>
<div class="subtle" id="school"></div><h1>教学支持与上传测试</h1><div id="course" class="subtle"></div><nav><a href="#readiness">上传测试</a><a href="#support">教学支持</a><a href="#growth">逐课改进</a><a href="#ai">DeepSeek入口</a></nav><div id="message" role="status"></div>
<section id="readiness"><h2>这节课准备到哪一步了</h2><div class="steps" id="steps"></div><p class="note" id="audioNote"></p><div class="checklist"><div><strong>先用一段短视频试跑</strong><p class="subtle">检查学生可见、音轨可听、手动画框能确认身份，再上传完整课堂。测试素材须在授权范围内。</p></div><div><strong>再检查整节课</strong><p class="subtle">核对视频时长、开头中间结尾、远处声音和重叠声；保留无回应与采集缺失的区别。</p></div></div><div class="actions"><a class="button" id="observeLink">复核关键片段</a><a class="button" id="batchLink">同课多视频</a></div></section>
<section id="support"><h2>按支持需求选择教学办法</h2><div class="support-grid"><div><label>本次重点支持需求<select id="need"></select></label><p class="subtle" id="related"></p><ul id="suggestions"></ul><p id="observe"></p></div><div><h3>评价先看教师能调整的环节</h3><p>先呈现本课亮点与一个可执行的改进目标，再查看证据和分数。</p><p class="note">漏录声音不记为学生无回应，也不据此给老师扣分。图卡、手势、AAC与约定动作可以是有效回应；不强行补分或设置保底分。</p><p class="subtle">病症以已有授权专业资料为准。本页不诊断、不自动开具治疗建议；具体支持由教师结合IEP和专业意见选择。</p></div></div><details><summary>近期参考依据与适用边界</summary><div id="references"></div></details></section>
<section id="growth"><h2>每节课只推进一个改进点</h2><p class="subtle">教师反思记录；不等同于经过验证的教学效果。学生量化变化另见同目标、同条件的长期测量。</p><form id="plan"><div class="fields"><label>上课日期<input type="date" id="lessonDate" required></label><label>本课观察目标<input id="goal" maxlength="1000" required></label><label>本课做得好的地方<textarea id="strength" maxlength="1000"></textarea></label><label>下次准备怎样调整<textarea id="nextAction" maxlength="1000" required></textarea></label><label>实施后观察到了什么<textarea id="outcome" maxlength="1000"></textarea></label><label>下次用什么证据核对变化<textarea id="nextCheck" maxlength="1000" required></textarea></label></div><div class="actions" style="margin-top:18px"><button class="primary" id="save" type="submit">保存本课改进记录</button><a class="button" href="/demo2/measurement">查看学生长期测量</a></div></form><h3>我的逐课记录</h3><div id="history"></div></section>
<section id="ai"><h2>DeepSeek解释入口</h2><p class="badge" id="modelStatus"></p><p id="modelBoundary" class="subtle"></p><div class="actions"><button id="preview">预览拟发送内容</button><button disabled title="API配置、授权及输出校验完成后开放">生成AI解释（待接入）</button></div><pre id="payload" hidden></pre><p class="subtle">接入后优先解释证据与可选教学建议；不更改教师评分，不将叫声或缺少语言推断为诊断。科研导出还需独立的数据授权和分析设计。</p></section>
</main><script>
'use strict';const $=id=>document.getElementById(id),taskId=new URLSearchParams(location.search).get('task_id')||'';let work,version=0;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(path,body){const r=await fetch('/api/v1/demo2'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,cache:'no-store',signal:AbortSignal.timeout(20000)});const j=await r.json();if(!r.ok)throw new Error(j.error?.message||j.message||'请求失败');return j;}
function need(){const n=work.needs[$('need').value];$('related').textContent=n.related;$('suggestions').innerHTML=n.actions.map(a=>'<li>'+esc(a)+'</li>').join('');$('observe').textContent='建议观察：'+n.observe;}
async function load(){work=(await api('/teaching-support?task_id='+encodeURIComponent(taskId))).workspace;$('school').textContent=work.course.school_context.school_name;$('course').textContent=work.course.course_name;$('steps').innerHTML=work.readiness.map((s,i)=>`<div class="step ${s.done?'ready':''}"><a href="${esc(s.url)}">${i+1}. ${esc(s.label)}</a><span>${s.done?'已有记录':'待完成'}</span></div>`).join('');$('audioNote').textContent=work.audio_note;$('need').innerHTML=Object.entries(work.needs).map(([k,v])=>`<option value="${k}">${esc(v.label)}</option>`).join('');$('references').innerHTML=work.references.map(r=>`<div class="reference"><a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${r.year} · ${esc(r.title)}</a><p>${esc(r.support)}</p><span class="subtle">${esc(r.limitation)}</span></div>`).join('');const p=work.plan;version=p?.version||0;const fields={lessonDate:'lesson_date',goal:'goal',strength:'strength',nextAction:'next_action',outcome:'outcome',nextCheck:'next_check'};for(const [id,key]of Object.entries(fields))$(id).value=p?.[key]||'';if(p)$('need').value=p.need;need();$('history').innerHTML=work.history.map(p=>`<div class="history"><strong>${esc(p.lesson_date)} · ${esc(p.course_name)} · v${p.version}</strong><p>目标：${esc(p.goal)}</p><p>亮点：${esc(p.strength||'待补充')}</p><p>调整：${esc(p.next_action)}</p><p>观察：${esc(p.outcome||'尚未回填，不能判断是否改善')}</p><p class="subtle">下次核对：${esc(p.next_check)}</p></div>`).join('')||'<p class="subtle">尚无逐课改进记录。</p>';$('modelStatus').textContent=work.deepseek.status;$('modelBoundary').textContent=work.deepseek.boundary;$('payload').hidden=true;}
$('need').onchange=need;$('preview').onclick=()=>{$('payload').textContent=JSON.stringify(work.preview,null,2);$('payload').hidden=false;};
$('plan').onsubmit=async e=>{e.preventDefault();$('save').disabled=true;try{await api('/teaching-support/plan',{task_id:taskId,expected_version:version,need:$('need').value,lesson_date:$('lessonDate').value,goal:$('goal').value,strength:$('strength').value,next_action:$('nextAction').value,outcome:$('outcome').value,next_check:$('nextCheck').value});await load();$('message').textContent='已保存。下次可回填实施效果；历史版本已保留。';}catch(e){$('message').textContent=e.message}finally{$('save').disabled=false}};
$('observeLink').href='/demo2/analysis?task_id='+encodeURIComponent(taskId);$('batchLink').href='/demo2/course-batch?task_id='+encodeURIComponent(taskId);load().catch(e=>$('message').textContent=e.message);
</script></body></html>'''
